CREATE TABLE "transactions" ("id" INTEGER NOT NULL, "amount" TEXT NOT NULL, "merchant_name" TEXT NOT NULL, "category" TEXT NOT NULL, "transaction_type" TEXT NOT NULL, "date_time" TEXT NOT NULL, "description" TEXT, "sms_body" TEXT, "bank_name" TEXT, "sms_sender" TEXT, "account_number" TEXT, "balance_after" TEXT, "transaction_hash" TEXT NOT NULL DEFAULT '', "is_recurring" INTEGER NOT NULL, "is_deleted" INTEGER NOT NULL DEFAULT 0, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "currency" TEXT NOT NULL DEFAULT 'INR', "from_account" TEXT, "to_account" TEXT, "reference" TEXT, "loan_id" INTEGER DEFAULT NULL, "loan_contribution" TEXT DEFAULT NULL, "receipt_path" TEXT DEFAULT NULL, "budget_category" TEXT DEFAULT NULL, "budget_impact_type" TEXT DEFAULT NULL, "group_id" INTEGER DEFAULT NULL, "profile_id" INTEGER DEFAULT NULL, "firefly_synced_at" TEXT DEFAULT NULL, "firefly_external_id" TEXT DEFAULT NULL, "firefly_last_error" TEXT DEFAULT NULL, "excluded_from_analytics" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "subscriptions" ("id" INTEGER NOT NULL, "merchant_name" TEXT NOT NULL, "amount" TEXT NOT NULL, "next_payment_date" TEXT, "state" TEXT NOT NULL, "bank_name" TEXT, "umn" TEXT, "category" TEXT, "sms_body" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "currency" TEXT NOT NULL DEFAULT 'INR', "direction" TEXT NOT NULL DEFAULT 'EXPENSE', "billing_cycle" TEXT NOT NULL DEFAULT 'Monthly', "last_paid_at" TEXT);
CREATE TABLE "chat_messages" ("id" TEXT NOT NULL, "message" TEXT NOT NULL, "isUser" INTEGER NOT NULL, "timestamp" INTEGER NOT NULL, "isSystemPrompt" INTEGER NOT NULL DEFAULT false);
CREATE TABLE "merchant_mappings" ("merchant_name" TEXT NOT NULL, "category" TEXT NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL);
CREATE TABLE "categories" ("id" INTEGER NOT NULL, "name" TEXT NOT NULL, "color" TEXT NOT NULL, "is_system" INTEGER NOT NULL, "is_income" INTEGER NOT NULL, "display_order" INTEGER NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL);
CREATE TABLE "account_balances" ("id" INTEGER NOT NULL, "bank_name" TEXT NOT NULL, "account_last4" TEXT NOT NULL, "balance" TEXT NOT NULL, "timestamp" TEXT NOT NULL, "transaction_id" INTEGER, "credit_limit" TEXT, "is_credit_card" INTEGER NOT NULL DEFAULT 0, "sms_source" TEXT, "source_type" TEXT, "account_type" TEXT, "created_at" TEXT NOT NULL, "currency" TEXT NOT NULL DEFAULT 'INR', "statement_day" INTEGER DEFAULT NULL, "profile_id" INTEGER NOT NULL DEFAULT 1, "alias" TEXT);
CREATE TABLE "unrecognized_sms" ("id" INTEGER NOT NULL, "sender" TEXT NOT NULL, "sms_body" TEXT NOT NULL, "received_at" TEXT NOT NULL, "reported" INTEGER NOT NULL, "is_deleted" INTEGER NOT NULL DEFAULT 0, "created_at" TEXT NOT NULL);
CREATE TABLE "cards" ("id" INTEGER NOT NULL, "card_last4" TEXT NOT NULL, "card_type" TEXT NOT NULL, "bank_name" TEXT NOT NULL, "account_last4" TEXT, "nickname" TEXT, "is_active" INTEGER NOT NULL DEFAULT 1, "last_balance" TEXT, "last_balance_source" TEXT, "last_balance_date" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "currency" TEXT NOT NULL DEFAULT 'INR');
CREATE TABLE "transaction_rules" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "priority" INTEGER NOT NULL, "conditions" TEXT NOT NULL, "actions" TEXT NOT NULL, "is_active" INTEGER NOT NULL, "is_system_template" INTEGER NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL);
CREATE TABLE "rule_applications" ("id" TEXT NOT NULL, "rule_id" TEXT NOT NULL, "rule_name" TEXT NOT NULL, "transaction_id" TEXT NOT NULL, "fields_modified" TEXT NOT NULL, "applied_at" TEXT NOT NULL, FOREIGN KEY("rule_id") REFERENCES "transaction_rules"("id") ON UPDATE NO ACTION ON DELETE CASCADE, FOREIGN KEY("transaction_id") REFERENCES "transactions"("id") ON UPDATE NO ACTION ON DELETE CASCADE);
CREATE TABLE "exchange_rates" ("id" INTEGER NOT NULL, "from_currency" TEXT NOT NULL, "to_currency" TEXT NOT NULL, "rate" TEXT NOT NULL, "provider" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "updated_at_unix" INTEGER NOT NULL DEFAULT 0, "expires_at" TEXT NOT NULL, "expires_at_unix" INTEGER NOT NULL DEFAULT 0, "is_custom_rate" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "budgets" ("id" INTEGER NOT NULL, "name" TEXT NOT NULL, "limit_amount" TEXT NOT NULL, "period_type" TEXT NOT NULL, "start_date" TEXT NOT NULL, "end_date" TEXT NOT NULL, "currency" TEXT NOT NULL DEFAULT 'INR', "is_active" INTEGER NOT NULL DEFAULT 1, "include_all_categories" INTEGER NOT NULL DEFAULT 0, "color" TEXT NOT NULL DEFAULT '#1565C0', "group_type" TEXT NOT NULL DEFAULT 'LIMIT', "display_order" INTEGER NOT NULL DEFAULT 0, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL);
CREATE TABLE "budget_categories" ("id" INTEGER NOT NULL, "budget_id" INTEGER NOT NULL, "category_name" TEXT NOT NULL, "budget_amount" TEXT NOT NULL DEFAULT '0', FOREIGN KEY("budget_id") REFERENCES "budgets"("id") ON UPDATE NO ACTION ON DELETE CASCADE);
CREATE TABLE "budget_month_snapshots" ("id" INTEGER NOT NULL, "budget_id" INTEGER NOT NULL, "year" INTEGER NOT NULL, "month" INTEGER NOT NULL, "budget_name" TEXT NOT NULL, "limit_amount" TEXT NOT NULL, "include_all_categories" INTEGER NOT NULL DEFAULT 0, "color" TEXT NOT NULL DEFAULT '#1565C0', "group_type" TEXT NOT NULL DEFAULT 'LIMIT', "display_order" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "budget_category_month_snapshots" ("id" INTEGER NOT NULL, "budget_id" INTEGER NOT NULL, "year" INTEGER NOT NULL, "month" INTEGER NOT NULL, "category_name" TEXT NOT NULL, "budget_amount" TEXT NOT NULL);
CREATE TABLE "transaction_splits" ("id" INTEGER NOT NULL, "transaction_id" INTEGER NOT NULL, "category" TEXT NOT NULL, "amount" TEXT NOT NULL, "created_at" TEXT NOT NULL, FOREIGN KEY("transaction_id") REFERENCES "transactions"("id") ON UPDATE NO ACTION ON DELETE CASCADE);
CREATE TABLE "bank_notifications" ("id" INTEGER NOT NULL, "package_name" TEXT NOT NULL, "sender_alias" TEXT NOT NULL, "message_body" TEXT NOT NULL, "message_hash" TEXT NOT NULL, "posted_at" TEXT NOT NULL, "processed" INTEGER NOT NULL, "transaction_id" INTEGER, "created_at" TEXT NOT NULL);
CREATE TABLE "loans" ("id" INTEGER NOT NULL, "person_name" TEXT NOT NULL, "direction" TEXT NOT NULL, "original_amount" TEXT NOT NULL, "remaining_amount" TEXT NOT NULL, "currency" TEXT NOT NULL DEFAULT 'INR', "status" TEXT NOT NULL DEFAULT 'ACTIVE', "note" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "settled_at" TEXT);
CREATE TABLE "transaction_groups" ("id" INTEGER NOT NULL, "name" TEXT NOT NULL, "note" TEXT DEFAULT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL);
CREATE TABLE "profiles" ("id" INTEGER NOT NULL, "name" TEXT NOT NULL, "color_hex" TEXT NOT NULL, "sort_order" INTEGER NOT NULL);